// intake.handoverCard.read — E2: the card a project's Intake tab shows. Generated by `pnpm gen:query`; acceptance
// cases added. Cards go through the real intake commands.
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, createFakeClock, createTestDatabase, type TestDatabase } from '@ocs/testing';
import { Forbidden, grantOf, openTestKernel, type TestKernel } from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { decideIntake } from '../commands/decide-intake.ts';
import { saveHandoverCard } from '../commands/save-handover-card.ts';
import { submitHandoverCard } from '../commands/submit-handover-card.ts';
import { handoverCardView } from '../queries/handover-card.ts';
import { itemCodes } from '../rules/handover-checklist.ts';

const sales = aStaffActor({ roles: ['sales'] });
const director = aStaffActor({ roles: ['director'] });
const clock = createFakeClock(new Date('2026-11-20T09:00:00Z'));
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
const read = () => t.kernel.read(handoverCardView, sales, { siteId: siteA });
const items = (except: string[]) =>
  itemCodes
    .filter((c) => !except.includes(c))
    .map((code) =>
      code.startsWith('F') ? { code, status: 'provided' } : { code, status: 'provided', value: 'in folder' },
    );
const save = (except: string[]) => {
  const content = { identification: { projectName: 'Counting', projectType: 'new' } };
  const card = {
    siteId: siteA,
    content,
    items: items(except),
    installsOrConfigures: true,
    newClientOrPlace: true,
  };
  return t.kernel.execute(saveHandoverCard, sales, card, 'test');
};

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url, { clock: clock.now });
  t.grant(director, createClient.permission, createSite.permission, decideIntake.permission);
  t.grant(sales, saveHandoverCard.permission, submitHandoverCard.permission, handoverCardView.permission);
  const a = await t.kernel.execute(
    createClient,
    director,
    { shortCode: 'CLIENTA', name: 'Client A' },
    'test',
  );
  const place = { countryCode: 'GB', cityCode: 'LON', cityName: 'London', name: 'Mall A', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, director, { clientId: a.id, ...place }, 'test'));
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('intake.handoverCard.read', () => {
  it('is for internal staff; not clients, partners, R&D or finance', async () => {
    expect(grantOf(handoverCardView.permission)?.roles).toEqual([
      'director',
      'management',
      'pm',
      'sales',
      'sponsor',
    ]);
    await expect(
      t.kernel.read(handoverCardView, aStaffActor({ roles: ['rnd'] }), { siteId: siteA }),
    ).rejects.toBeInstanceOf(Forbidden);
  });

  it('no card yet: null; a draft shows its package, items and what still blocks submission', async () => {
    expect(await read()).toBeNull();
    await save(['A2', 'G1']);
    const card = await read();
    expect(card).toMatchObject({
      version: 1,
      status: 'draft',
      package: 'full',
      decision: null,
      conditionalStart: null,
    });
    expect(card?.gaps.map((g) => g.code)).toEqual(['A2', 'G1']);
  });

  it('after the decision: status, decision and its conditions', async () => {
    await save([]);
    await t.kernel.execute(submitHandoverCard, sales, { siteId: siteA }, 'test');
    const condition = { itemCode: 'B2', text: 'secondary contact', deadline: '2026-11-24' };
    const decision = {
      siteId: siteA,
      decision: 'accepted_with_conditions',
      folderStandard: 'L',
      conditions: [condition],
    };
    await t.kernel.execute(decideIntake, director, decision, 'test');
    const card = await read();
    expect([card?.status, card?.gaps]).toEqual(['accepted_with_conditions', []]);
    expect(card?.decision?.conditions).toEqual([{ ...condition, status: 'open' }]);
  });
});
